CREATE DATABASE IF NOT EXISTS jobcom CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE jobcom;
CREATE TABLE IF NOT EXISTS admins(id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,display_name VARCHAR(120) NOT NULL DEFAULT 'Administrator',role ENUM('SUPER_ADMIN','ADMIN') NOT NULL DEFAULT 'ADMIN',status ENUM('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fields(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS job_types(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skills(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(100),phone VARCHAR(40),date_of_birth DATE,address VARCHAR(300),city VARCHAR(100),state VARCHAR(100),postal_code VARCHAR(20),qualification VARCHAR(180),career_field VARCHAR(120),experience_years DECIMAL(5,2),skills TEXT,profile_headline VARCHAR(220),profile_summary TEXT,linkedin_url VARCHAR(500),portfolio_url VARCHAR(500),profile_photo_path VARCHAR(500),resume_path VARCHAR(500),government_id_type VARCHAR(80),government_id_last4 CHAR(4),government_id_document_path VARCHAR(500),id_verification_status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',status ENUM('PENDING','ACTIVE','REJECTED','BLOCKED') NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(id_verification_status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS companies(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(100),legal_name VARCHAR(180),contact_person VARCHAR(160),contact_title VARCHAR(100),phone VARCHAR(40),website VARCHAR(500),industry VARCHAR(120),company_size VARCHAR(60),license_number VARCHAR(100),license_type VARCHAR(100),license_document_path VARCHAR(500),company_registration_number VARCHAR(100),tax_registration_number VARCHAR(100),address VARCHAR(300),city VARCHAR(100),state VARCHAR(100),country VARCHAR(100),postal_code VARCHAR(20),verification_status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',status ENUM('PENDING','APPROVED','REJECTED','BLOCKED') NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(verification_status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS jobs(id BIGINT AUTO_INCREMENT PRIMARY KEY,company_id BIGINT,title VARCHAR(200) NOT NULL,description TEXT,job_type_id BIGINT,package_ctc VARCHAR(180),career_field VARCHAR(120),status ENUM('PENDING','VERIFIED','REJECTED','DELETED') NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL,FOREIGN KEY(job_type_id) REFERENCES job_types(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS applications(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_id BIGINT NOT NULL,user_id BIGINT NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'APPLIED',resume_path VARCHAR(500) NULL,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_application_job_user(job_id,user_id),FOREIGN KEY(job_id) REFERENCES jobs(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS application_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,application_id BIGINT NOT NULL,sender_type ENUM('SEEKER','RECRUITER') NOT NULL,sender_id BIGINT NOT NULL,body VARCHAR(4000) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(application_id,created_at),FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS practice_sets(id BIGINT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,url VARCHAR(1000) NOT NULL,skill_id BIGINT,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assessments(id BIGINT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,file_path VARCHAR(500) NOT NULL,company_name VARCHAR(120) NOT NULL DEFAULT 'General',role_name VARCHAR(120) NOT NULL DEFAULT 'General',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_assessment_company_role(company_name,role_name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resumes(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,file_path VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resume_templates(template_id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,description VARCHAR(500) NOT NULL DEFAULT '',layout VARCHAR(40) NOT NULL DEFAULT 'classic',file_path VARCHAR(500) NULL,active TINYINT(1) NOT NULL DEFAULT 1,uploaded_by BIGINT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resume_drafts(draft_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,template_id BIGINT NOT NULL,title VARCHAR(180) NOT NULL,resume_data LONGTEXT NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_resume_user_title(user_id,title),INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,audience VARCHAR(40) NOT NULL,subject VARCHAR(180) NOT NULL,body TEXT NOT NULL,admin_id BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,message_id BIGINT NOT NULL,read_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS support_conversations(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,requester_type VARCHAR(20) NOT NULL DEFAULT 'SEEKER',category VARCHAR(20) NOT NULL,subject VARCHAR(180) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_support_user_updated(user_id,updated_at),INDEX idx_support_status_updated(status,updated_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS support_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT NOT NULL,sender_type VARCHAR(20) NOT NULL,sender_id BIGINT NOT NULL,body VARCHAR(4000) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_support_messages_thread(conversation_id,id),FOREIGN KEY(conversation_id) REFERENCES support_conversations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT,action VARCHAR(100) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id BIGINT,details VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL) ENGINE=InnoDB;
